<?php
namespace App\Http\Controllers;
use App\Services\{RecordImport,ImportPolicy,ImportStaging,ContactImportCache,SalonStore,WorkspaceAccess};
use Illuminate\Http\Request;
final class RecordImportController
{
 public function preview(Request $r,string $kind){WorkspaceAccess::admin($r,true);$v=$r->validate(['records'=>'required|array|min:1|max:2000','records.*'=>'required|array','policy'=>'required|in:fill,overwrite,skip']);$v['records']=array_map(function($row){if(empty($row['id']))$row['id']=(string)\Illuminate\Support\Str::uuid();return $row;},$v['records']);$items=RecordImport::preview(app(SalonStore::class)->read(),$kind,$v['records'],$v['policy']);$id=ImportStaging::create($r,'record-import',['kind'=>$kind,'records'=>$v['records'],'policy'=>$v['policy'],'items'=>$items]);return response()->json(['id'=>$id,'items'=>$items,'policy'=>$v['policy'],'summary'=>ImportPolicy::summary($items)]);}
 public function commit(Request $r,string $kind){WorkspaceAccess::admin($r,true);$v=$r->validate(['id'=>'required|uuid','selected'=>'required|array|min:1|max:2000','selected.*'=>'required|integer|min:0|max:1999|distinct']);$key=ImportStaging::key($r,'record-import',$v['id']);$result=ContactImportCache::store()->lock($key.':lock',30)->block(3,function()use($r,$v,$key,$kind){$d=ImportStaging::read($r,'record-import',$v['id']);if(isset($d['result']))return $d['result'];abort_unless($d['kind']===$kind,422);$result=app(SalonStore::class)->mutate(function(&$s)use($d,$v,$kind){$result=['added'=>0,'updated'=>0,'skipped'=>0];foreach($v['selected'] as $index){$item=$d['items'][$index]??null;if(!$item||!in_array($item['status'],['new','update','same'],true)){++$result['skipped'];continue;}$record=$d['records'][$index];try{$match=RecordImport::find($s,$kind,$record);}catch(\InvalidArgumentException){++$result['skipped'];continue;}$current=$match===null?null:$s[$kind][$match];if(($current['id']??null)!==($item['existingId']??null)||($current?hash('sha256',json_encode($current)):null)!==($item['fingerprint']??null)){++$result['skipped'];continue;}$r=RecordImport::apply($s,$kind,[$record],$d['policy']);foreach($result as $k=>$_)$result[$k]+=$r[$k];}return $result;},false);ImportStaging::put($key,['result'=>$result]);return $result;});return response()->json($result);}
}
